# Autogenerated-equivalent pattern for TileLangIR custom dialect.
# Hand-written to avoid mlir-tblgen dependency.

from mlir.dialects._ods_common import _cext as _ods_cext
from mlir.dialects._ods_common import (
    get_default_loc_context as _ods_get_default_loc_context,
)
_ods_ir = _ods_cext.ir

import builtins


# ---------------------------------------------------------------------------
# Dialect
# ---------------------------------------------------------------------------


@_ods_cext.register_dialect
class _Dialect(_ods_ir.Dialect):
    DIALECT_NAMESPACE = "tilelang"



# ===========================================================================
# tilelang.pipeline_stage
# ===========================================================================


@_ods_cext.register_operation(_Dialect)
class PipelineStageOp(_ods_ir.OpView):
    """Internal source statement boundary for OpenTileAS pipeline planning."""

    OPERATION_NAME = "tilelang.pipeline_stage"
    _ODS_REGIONS = (1, True)

    def __init__(self, *, label=None, loc=None, ip=None):
        attributes = {}
        if label is not None:
            attributes["label"] = _ods_ir.StringAttr.get(label)
        super().__init__(
            self.OPERATION_NAME,
            self._ODS_REGIONS,
            None,
            None,
            attributes=attributes,
            results=[],
            operands=[],
            successors=None,
            regions=None,
            loc=loc,
            ip=ip,
        )

    @property
    def body(self):
        return self.regions[0]

# ===========================================================================
# tilelang.copy
# ===========================================================================

@_ods_cext.register_operation(_Dialect)
class CopyOp(_ods_ir.OpView):
    """Copy between two memref/view SSA values.

    Assembly (unregistered dialect form)::

        "tilelang.copy"(%src, %dst) : (memref<...>, memref<...>) -> ()
    """

    OPERATION_NAME = "tilelang.copy"

    _ODS_REGIONS = (0, True)

    def __init__(
        self,
        src,
        dest,
        *,
        split_dim: int | None = None,
        transpose: bool | None = None,
        loc: _ods_ir.Location | None = None,
        ip: _ods_ir.InsertionPoint | None = None,
    ):
        attributes: dict = {}
        if split_dim is not None:
            attributes["split_dim"] = _ods_ir.IntegerAttr.get(
                _ods_ir.IntegerType.get_signless(64), split_dim
            )
        if transpose:
            attributes["transpose"] = _ods_ir.UnitAttr.get(
                _ods_get_default_loc_context(loc)
            )
        super().__init__(
            self.OPERATION_NAME,
            self._ODS_REGIONS,
            None,  # _ODS_OPERAND_SEGMENTS
            None,  # _ODS_RESULT_SEGMENTS
            attributes=attributes,
            results=[],
            operands=[src, dest],
            successors=None,
            regions=None,
            loc=loc,
            ip=ip,
        )

    @builtins.property
    def src(self):
        return self.operation.operands[0]

    @builtins.property
    def dest(self):
        return self.operation.operands[1]

    @builtins.property
    def split_dim(self) -> int | None:
        if "split_dim" not in self.operation.attributes:
            return None
        return _ods_ir.IntegerAttr(self.operation.attributes["split_dim"]).value

    @split_dim.setter
    def split_dim(self, value: int | None):
        if value is not None:
            self.operation.attributes["split_dim"] = _ods_ir.IntegerAttr.get(
                _ods_ir.IntegerType.get_signless(64), value
            )
        elif "split_dim" in self.operation.attributes:
            del self.operation.attributes["split_dim"]

    @builtins.property
    def transpose(self) -> bool:
        return "transpose" in self.operation.attributes

    @transpose.setter
    def transpose(self, value: bool):
        if value:
            self.operation.attributes["transpose"] = _ods_ir.UnitAttr.get()
        elif "transpose" in self.operation.attributes:
            del self.operation.attributes["transpose"]


